try{if(localStorage.getItem('stack-lab-stage-source-v1')==='compare')$('#stage-source').value='compare';}catch{}
$('#stage-source').onchange=()=>{try{localStorage.setItem('stack-lab-stage-source-v1',$('#stage-source').value);}catch{}load();};
