function renderPressureCases(report){const scan=report.pressureCases;if(!scan)return null;const section=el('section',undefined,'stage-pressure-results');section.append(el('h3','심해 · 수압 단계별 클리어 후보'),el('p','적용 전: '+(report.firstRisk===null?'모든 검증 라운드 통과':report.firstRisk+'R부터 위험')+' · 후보는 잔존 몬스터·흡수·누적 생명을 반영한 100R 연속 전투를 통과해야 표시합니다. 기존 구매에 추가하며 수압 단계는 유지 상한이며 라운드별 자연 수압을 반영합니다.'));const found=scan.cases.filter(c=>c.verified);if(found.length){const low=found[0],uncertain=scan.cases.some(c=>c.level<low.level&&c.cutoff),cheap=[...found].sort((a,b)=>a.cost-b.cost||a.level-b.level)[0];section.append(el('p',(uncertain?'발견된 후보 중 최저':'탐색 상한 내 확인된 최저')+' 수압 '+low.level+'단계 · 해당 단계 최소 추가 '+low.cost+'진주 / 1인 · 발견된 후보 중 최소 비용 '+cheap.cost+'진주 (수압 '+cheap.level+'단계)'));}const table=el('table',undefined,'stage-table'),head=el('tr');for(const h of ['수압','최소 추가 진주 / 1인','후보 조합 / 결과'])head.append(el('th',h));table.append(head);for(const c of scan.cases){const row=el('tr');row.append(el('td',c.level+'단계'),el('td',c.verified?c.cost+'개':c.cutoff?'미확정':'후보 없음'));const counts=new Map;for(const key of c.keys||[])counts.set(key,(counts.get(key)||0)+1);const labels={1:'공격력 +100%',8:'공격력 +300%',2:'공속 +25%',9:'공속 +50%',3:'치명피해 +100%',10:'치명피해 +300%',4:'기본 공격력 +5%',12:'기본 공격력 +15%',5:'기본 공속 +15%',13:'기본 공속 +30%',6:'방감 +10%',14:'방감 +25%'};row.append(el('td',c.verified?([...counts].map(([key,n])=>labels[key]+' ×'+n).join(' / ')||'추가 구매 없음')+' · 100R 연속 전투 통과':c.cutoff?'계산 제한으로 최소치 미확정':'지정한 추가 진주 상한 내 클리어 후보 없음'));table.append(row);}const wrap=el('div',undefined,'stage-table-wrap');wrap.append(table);section.append(wrap,el('p',scan.evaluated+'개 후보 검토 · 일반 진주 12종 / 수압 유지 상한 / 감압·재화 획득·구매 순서 제외 · 시작부터 진주를 보유하는 시나리오이며 실전 클리어 보장은 아닙니다.'));return section;}
